module top_pad (
	clk, 
	rst, 
	sclk, 
	cs_n, 
	mosi, 
	miso);
   input clk;
   input rst;
   input sclk;
   input cs_n;
   input mosi;
   output miso;

   // Internal wires
   wire VSS;
   wire VDD;
   wire clk_PAD;
   wire cs_n_PAD;
   wire miso_PAD;
   wire mosi_PAD;
   wire rst_PAD;
   wire sclk_PAD;

   // Module instantiations
   pad_corner corner0 (
	.VSS(VSS), 
	.VDD(VDD));
   pad_corner corner1 (
	.VSS(VSS), 
	.VDD(VDD));
   pad_corner corner2 (
	.VSS(VSS), 
	.VDD(VDD));
   pad_corner corner3 (
	.VSS(VSS), 
	.VDD(VDD));
   pad_vdd vdd0 (
	.VSS(VSS), 
	.VDD(VDD));
   pad_gnd vss0 (
	.VSS(VSS), 
	.VDD(VDD));
   pad_in clk_pad (
	.DataIn(clk_PAD),
	.pad(clk), 
	.VSS(VSS), 
	.VDD(VDD));
   TopModule core (
	.clk(clk_PAD),
	.rst(rst_PAD),
	.sclk(sclk_PAD),
	.cs_n(cs_n_PAD),
	.mosi(mosi_PAD),
	.miso(miso_PAD), 
	.VDD(VDD), 
	.VSS(VSS));
   pad_in cs_n_pad (
	.DataIn(cs_n_PAD),
	.pad(cs_n), 
	.VSS(VSS), 
	.VDD(VDD));
   pad_out miso_pad (
	.pad(miso),
	.DataOut(miso_PAD), 
	.VSS(VSS), 
	.VDD(VDD));
   pad_in mosi_pad (
	.DataIn(mosi_PAD),
	.pad(mosi), 
	.VSS(VSS), 
	.VDD(VDD));
   pad_in rst_pad (
	.DataIn(rst_PAD),
	.pad(rst), 
	.VSS(VSS), 
	.VDD(VDD));
   pad_in sclk_pad (
	.DataIn(sclk_PAD),
	.pad(sclk), 
	.VSS(VSS), 
	.VDD(VDD));
endmodule

